function referenceDashboard(){const t=totals(),events=homeEvents(),items=obligations(),cash=t.cash,incoming=expectedThisMonth(),need=Math.max(0,t.debts-cash-incoming),coverage=Math.min(100,Math.max(0,(cash+incoming)/(t.debts||1)*100)),money=(value)=>rub(value);const cards=[['▤','На картах и счетах',cash,'Свободные деньги',''],['▥','Вклады',t.deposits,`${state.deposits.length} ${plural(state.deposits.length,'вклад','вклада','вкладов')}`,''],['↗','Ожидается в '+monthInName(),incoming,currentMonthRangeText(),'attention'],['⌂','Имущество',t.assets,'Оценочная стоимость',''],['◴','Обязательства',t.debts,items.length?`Ближайший платёж · ${dateText(items.flatMap(o=>o.allPayments||[]).sort((a,b)=>a.date.localeCompare(b.date))[0]?.date)}`:'Платежей нет','danger'],['◈','Чистый капитал',t.net,'Текущий капитал','positive']];const cardHtml=cards.map(c=>`<div class="dash-stat ${c[4]}"><span class="dash-stat-icon">${c[0]}</span><span class="dash-stat-label">${c[1]}</span><strong>${money(c[2])}</strong><small>${c[3]}</small></div>`).join('');const eventHtml=events.map(e=>`<div class="dash-event${e.attention?' is-'+e.attention:''}" data-event-id="${escText(e.id||'')}" onclick="openCalendarEvent(this.dataset.eventId)"><span class="dash-event-date">${dateText(e.date)}</span><span class="dash-event-dot ${e.type==='payment'||e.attention==='overdue'?'pay':e.type==='end'?'end':'income'}"></span><span class="dash-event-title"><b>${escText(e.label||e.title||'')}</b><span>${escText(e.primary||e.sub||'')}</span>${e.secondary?`<small>${escText(e.secondary)}</small>`:''}${e.attention?(e.noteLines||[]).map(line=>`<em>${escText(line)}</em>`).join(''):''}</span><strong>${escText(e.amountText||(e.amount?money(Math.abs(e.amount)):'—'))}${e.rubHint?`<small>${escText(e.rubHint)}</small>`:''}</strong></div>`).join('');const snaps=(state.history||[]).slice(-7).filter(h=>h&&h.date),hasChart=snaps.length>1,values=snaps.map(h=>num(h.net)),min=hasChart?Math.min(...values):0,range=hasChart?(Math.max(...values)-min)||1:1,points=hasChart?values.map((v,i)=>`${i*(100/(values.length-1))},${88-(v-min)/range*65}`).join(' '):'',chartLabels=hasChart?snaps.map((h,i)=>`<span>${i===snaps.length-1?'Сейчас':dateText(h.date)}</span>`).join(''):'',growthLabel=growthCaption(money);const obligationHtml=items.slice(0,2).map(o=>{const stages=(o.allPayments||[]).slice(0,4).map(p=>`<div class="dash-stage ${p.status==='Оплачено'?'paid':''} ${p.status!=='Оплачено'&&p.date===o.nextDate?'next':''}"><b>${p.status==='Оплачено'?'✓ ':''}${money(p.amount)}</b><small>${p.status==='Оплачено'?'Оплачено':dateText(p.date)}</small></div>`).join('');return `<div class="dash-obligation"><div class="dash-obligation-top"><div><span class="dash-mini-icon">▥</span><strong>${o.what}</strong><small>${money(o.total)} · осталось ${money(o.remaining)}</small></div><span class="dash-paid">Оплачено: ${money(o.paid)}</span></div><div class="dash-stages">${stages||'<small class="muted">График платежей не задан</small>'}</div></div>`}).join('');return `<div class="dashboard-shell"><div class="dash-stat-grid">${cardHtml}</div><div class="dash-main-grid"><section class="dash-goal panel"><div class="dash-panel-heading"><div><p class="eyebrow">ФИНАНСОВАЯ ЦЕЛЬ</p><h3>Финансовая обеспеченность</h3><span>Покрытие будущих обязательств доступными деньгами и поступлениями</span></div><span class="dash-percent">${Math.round(coverage)}%</span></div><div class="dash-progress"><i style="width:${coverage}%"></i></div><div class="dash-goal-caption"><strong>${money(Math.min(cash+incoming,t.debts))}</strong><span>из ${money(t.debts)}</span></div><div class="dash-goal-facts"><div><small>Доступно сейчас</small><b>${money(cash)}</b></div><div><small>Планируемые поступления</small><b>${money(incoming)}</b></div><div><small>Нужно обеспечить</small><b class="${need?'orange':'teal'}">${need?money(need):'Средств достаточно'}</b></div></div></section><section class="dash-events panel"><div class="dash-panel-heading"><div><p class="eyebrow">ПЛАНИРОВАНИЕ</p><h3>Ближайшие события</h3></div><button class="ghost-button" onclick="setView('calendar')">Все события →</button></div><div class="dash-event-list">${eventHtml||'<div class="empty">Событий пока нет</div>'}</div></section></div><div class="dash-lower-grid"><section class="dash-chart panel"><div class="dash-panel-heading"><div><p class="eyebrow">ДИНАМИКА</p><h3>Динамика капитала</h3></div><button class="ghost-button" onclick="setView('history')">За период⌄</button></div>${hasChart?`<div class="line-chart"><div class="chart-grid-lines"><i></i><i></i><i></i><i></i></div><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="Динамика капитала"><polyline points="${points}" fill="none" stroke="#ff9e3d" stroke-width="2.2" vector-effect="non-scaling-stroke"/><polyline points="${points} 100,100 0,100" fill="#ff9e3d" opacity=".13" stroke="none"/></svg><div class="chart-labels">${chartLabels}</div></div>`:'<div class="empty">Снимка ещё нет</div>'}<div class="dash-chart-foot"><span>${growthLabel}</span><span>◈ <b>${money(t.net)}</b> текущий капитал</span></div></section><section class="dash-obligations panel"><div class="dash-panel-heading"><div><p class="eyebrow">КОНТРОЛЬ ПЛАТЕЖЕЙ</p><h3>Обязательства</h3></div><button class="primary-button" onclick="setView('debts')">＋ Добавить</button></div><div class="dash-obligation-list">${obligationHtml||'<div class="empty">Обязательств пока нет</div>'}</div></section></div></div>`}
