const KEY='finance-cabinet-v1';
const today=new Date();
const isoDate=d=>{if(typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d))return d;const date=d instanceof Date?d:new Date(d);return date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0')};
function roundMoney(n){const value=Number(n);if(!Number.isFinite(value))return 0;return Math.round((value+Math.sign(value)*1e-10)*100)/100}
function moneyGrouped(n){const value=roundMoney(n);const digits=Math.abs(Math.round(value*100))%100===0?0:2;return new Intl.NumberFormat('ru-RU',{minimumFractionDigits:digits,maximumFractionDigits:digits}).format(value)}
function formatMoneyInput(value){if(value==null||value==='')return '';const raw=String(value).replace(/\s/g,'').replace(/\./g,',');if(!raw)return '';const negative=raw.charAt(0)==='-';const body=negative?raw.slice(1):raw;const pieces=body.split(',');let intPart=(pieces[0]||'').replace(/\D/g,'');intPart=intPart.replace(/^0+(?=\d)/,'');if(!intPart)intPart=pieces.length>1?'0':'';intPart=intPart.replace(/\B(?=(\d{3})+(?!\d))/g,' ');if(pieces.length===1)return (negative?'-':'')+intPart;const frac=pieces.slice(1).join('').replace(/\D/g,'').slice(0,2);return (negative?'-':'')+intPart+','+frac}
function normalizeMoneyInput(value,pad){const formatted=formatMoneyInput(value);if(!formatted||!pad||formatted.indexOf(',')<0)return formatted;const parts=formatted.split(',');const frac=(parts[1]||'').replace(/\D/g,'');if(!frac||Number(frac)===0)return parts[0];return parts[0]+','+(frac+'00').slice(0,2)}
