const dateText=d=>{if(!d)return '—';const date=new Date(d+'T12:00:00');if(Number.isNaN(date.getTime()))return '—';return String(date.getDate()).padStart(2,'0')+'.'+String(date.getMonth()+1).padStart(2,'0')+'.'+String(date.getFullYear()).slice(-2)};
function monthInName(date){return ['январе','феврале','марте','апреле','мае','июне','июле','августе','сентябре','октябре','ноябре','декабре'][(date||today).getMonth()]}
function inCurrentMonth(date){return !!date&&String(date).slice(0,7)===isoDate(today).slice(0,7)}
function currentMonthRangeText(){const start=new Date(today.getFullYear(),today.getMonth(),1),end=new Date(today.getFullYear(),today.getMonth()+1,0);return dateText(isoDate(start))+'–'+dateText(isoDate(end))}
function expectedThisMonth(){let sum=0;state.deposits.forEach(function(d){if(!d.closed&&d.status!=='Получено'&&inCurrentMonth(d.nextDate))sum+=num(d.expected)});return sum}
function depositMonthForecast(){const names=['Январь','Февраль','Март','Апрель','Май','Июнь','Июль','Август','Сентябрь','Октябрь','Ноябрь','Декабрь'];const groups={};let total=0;state.deposits.forEach(function(d){if(d.closed||d.status==='Получено'||!d.nextDate||!(num(d.expected)>0))return;const key=String(d.nextDate).slice(0,7);groups[key]=(groups[key]||0)+num(d.expected);total+=num(d.expected)});const rows=Object.keys(groups).sort().map(function(key){const parts=key.split('-');return '<div class="stat-row"><span class="deposit-month-name">'+names[Number(parts[1])-1]+' '+parts[0]+'</span><strong>'+rub(groups[key])+'</strong></div>'}).join('');return '<div class="panel deposit-months"><div class="section-heading"><div><p class="eyebrow">ПРОГНОЗ ВЫПЛАТ</p><h3>Будущие поступления по месяцам</h3><p>Каждая сумма стоит в месяце выплаты и не попадает в другой месяц.</p></div></div>'+(rows||'<div class="empty">Ожидаемых выплат нет</div>')+'<div class="stat-row deposit-months-total"><span>Всего ожидается по вкладам</span><strong>'+rub(total)+'</strong></div></div>'}
