function normalizeState(data){const next=data||JSON.parse(JSON.stringify(seed));next.accounts=Array.isArray(next.accounts)?next.accounts:[];next.deposits=Array.isArray(next.deposits)?next.deposits:[];next.assets=Array.isArray(next.assets)?next.assets:[];next.debts=Array.isArray(next.debts)?next.debts:[];if(!Array.isArray(next.currencyCatalog))next.currencyCatalog=[];next.accounts.forEach(item=>{if(item.coverObligations===undefined)item.coverObligations=true;if(!Array.isArray(item.movements))item.movements=[]});next.deposits.forEach(item=>{if(item.coverObligations===undefined)item.coverObligations=true;if(item.current==null||item.current==='')item.current=num(item.initial);if(!Array.isArray(item.movements))item.movements=[];if(!Array.isArray(item.allocations))item.allocations=[];if(!item.purpose)item.purpose='free'});const typeMap={'Земля':'Земельный участок','Здание':'Территория или имущественный комплекс','Квартира':'Квартира','Дом':'Дом','Коммерческое помещение':'Коммерческое помещение','Автомобиль':'Автомобиль','Склад':'Склад','Земельный участок':'Земельный участок','Территория или имущественный комплекс':'Территория или имущественный комплекс','Другое':'Другое'};const usageMap={'Использую в своём бизнесе':'Используется в собственном бизнесе','Сдаётся в аренду':'Сдаётся в аренду','Планирую сдавать':'Планируется сдача в аренду','Свободно / ищу арендатора':'Не используется / свободно','Оплачиваю':'Личное использование','Продано / выбыло':'Не используется / свободно','Личное использование':'Личное использование','Используется в собственном бизнесе':'Используется в собственном бизнесе','Планируется сдача в аренду':'Планируется сдача в аренду','Не используется / свободно':'Не используется / свободно'};next.assets.forEach(asset=>{if(!asset.type)asset.type=asset.category||'Другое';if(typeMap[asset.type])asset.type=typeMap[asset.type];if(!asset.ownershipStatus){const base=asset.paidBase===undefined?num(asset.paid):num(asset.paidBase);const paid=base+assetPayments(asset).filter(payment=>payment.status==='Оплачено').reduce((sum,payment)=>sum+num(payment.amount),0);const left=Math.max(0,num(asset.price)-paid);asset.ownershipStatus=asset.status==='Покупаю'||(left>0&&asset.status!=='В собственности'&&asset.status!=='Оплачено')?'Покупается':'В собственности'}if(!asset.valueCurrency)asset.valueCurrency=asset.currency||'RUB';if(!asset.usage)asset.usage=usageMap[asset.usageStatus]||(asset.rent&&asset.rent.planned?'Планируется сдача в аренду':'Личное использование');if(asset.usage)asset.usageStatus=asset.usage;if(!Array.isArray(asset.parts))asset.parts=[];if(asset.acquisition===undefined)asset.acquisition=asset.purchase||'';if(!asset.status)asset.status=asset.ownershipStatus==='Покупается'?'Покупаю':'В собственности'});next.debts=next.debts.filter(d=>!next.assets.some(a=>a.name===d.what&&num(a.price)===num(d.total)&&num(a.paid)===num(d.paid)));next.debts.forEach(d=>{if(!Array.isArray(d.movements))d.movements=[]});return next}
let state=normalizeState(JSON.parse(localStorage.getItem(KEY)||'null')||seed); let activeView='dashboard'; let calendarMonth=new Date(today.getFullYear(),today.getMonth(),1);
function photoNeedsCompress(url){return typeof url==='string'&&url.indexOf('data:image/')===0&&!(url.indexOf('data:image/jpeg')===0&&url.length<180000)}
function compressImageUrl(url){return new Promise(function(resolve){if(!photoNeedsCompress(url)){resolve(url);return}const image=new Image();image.onload=function(){const shortSide=Math.min(image.width,image.height)||1;if(url.indexOf('data:image/jpeg')===0&&shortSide<=720){resolve(url);return}const scale=shortSide>720?720/shortSide:1,width=Math.max(1,Math.round(image.width*scale)),height=Math.max(1,Math.round(image.height*scale)),canvas=document.createElement('canvas'),context=canvas.getContext('2d');canvas.width=width;canvas.height=height;context.fillStyle='#ffffff';context.fillRect(0,0,width,height);context.drawImage(image,0,0,width,height);resolve(canvas.toDataURL('image/jpeg',0.72))};image.onerror=function(){resolve(url)};image.src=url})}
