function writeState(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(error){const quota=error&&(error.name==='QuotaExceededError'||error.name==='NS_ERROR_DOM_QUOTA_REACHED'||error.code===22);alert(quota?'Не удалось сохранить данные: в браузере не хватает места. Удалите часть фотографий или записей и попробуйте снова.':'Не удалось сохранить данные.')}}
async function compressStatePhotos(){for(const asset of state.assets||[]){if(Array.isArray(asset.photos))asset.photos=await Promise.all(asset.photos.map(compressImageUrl));if(asset.photo)asset.photo=await compressImageUrl(asset.photo);if(Array.isArray(asset.photos)&&asset.photos[0])asset.photo=asset.photos[0]}}
