const CURRENCY_OTHER='__OTHER__';
const CURRENCY_ADD='__ADD__';
const CURRENCY_MAIN=[{code:'RUB',title:'Российский рубль'},{code:'USD',title:'Доллар США'},{code:'EUR',title:'Евро'},{code:'AED',title:'Дирхам ОАЭ'}];
