function currencyCustom(){return Array.isArray(state.currencyCatalog)?state.currencyCatalog:[]}
function currencyAll(){const list=CURRENCY_MAIN.concat(CURRENCY_EXTRA);currencyCustom().forEach(function(item){if(item&&item.code&&!list.some(function(known){return known.code===item.code}))list.push({code:item.code,title:item.title||item.code})});return list}
function currencyTitle(code){const found=currencyAll().filter(function(item){return item.code===code})[0];return found?found.code+' — '+found.title:(code||'')}
