function addCatalogCurrency(code,title){const clean=String(code||'').trim().toUpperCase().replace(/[^A-Z]/g,'').slice(0,6);const name=String(title||'').trim();if(clean.length<3)return {ok:false,message:'Укажите код валюты из 3–6 латинских букв.'};if(!name)return {ok:false,message:'Укажите название валюты.'};if(!currencyAll().some(function(item){return item.code===clean})){state.currencyCatalog.push({code:clean,title:name});save()}document.querySelectorAll('select[data-currency-bound="1"]').forEach(function(select){if(select._currencyRefresh)select._currencyRefresh()});return {ok:true,code:clean}}
window.currencyCatalog={OTHER:CURRENCY_OTHER,ADD:CURRENCY_ADD,main:function(){return CURRENCY_MAIN.slice()},extra:function(){return CURRENCY_EXTRA.concat(currencyCustom())},all:currencyAll,title:currencyTitle,isMain:currencyIsMain,add:addCatalogCurrency};
window.amountInRub=function(amount,currency,rate){const code=currency||'RUB';const value=num(amount);if(!code||code==='RUB')return value;const fx=num(rate);return fx>0?roundMoney(value*fx):0};
function accountRub(account){return amountInRub(account&&account.balance,account&&account.currency,account&&account.fxRate)}
function accountMoney(account){const code=(account&&account.currency)||'RUB';if(code==='RUB')return rub(account.balance);const original=typeof moneyOriginal==='function'?moneyOriginal(account.balance,code):(moneyGrouped(account.balance)+' '+code);const eq=num(account.fxRate)>0?rub(accountRub(account)):'курс не задан';return original+'<br><span class="muted">'+eq+'</span>'}
