function assetPayments(a){return Array.isArray(a.payments)?a.payments:[]}
function assetPaid(a){const base=a.paidBase===undefined?num(a.paid):num(a.paidBase);return base+assetPayments(a).filter(p=>p.status==='Оплачено').reduce((s,p)=>s+num(p.amount),0)}
function assetRemaining(a){if(a.ownershipStatus&&a.ownershipStatus!=='Покупается')return 0;return Math.max(0,num(a.price)-assetPaid(a))}
function isWeekend(date){if(!date)return false;const day=new Date(date+'T12:00:00').getDay();return day===0||day===6}
function weekendNotice(date){return isWeekend(date)?'<div class="weekend-warning">Дата платежа приходится на выходной. Рекомендуем перенести оплату заранее.</div>':''}
function manualDebtRemaining(d){return Math.max(0,num(d.total)-num(d.paid))}
function obligations(){const items=[];state.assets.forEach(a=>{const allPayments=assetPayments(a).slice().sort((x,y)=>x.date.localeCompare(y.date)),payments=allPayments.filter(p=>p.status!=='Оплачено'),remaining=assetRemaining(a);if(remaining>0||payments.length)items.push({id:`asset-${a.id}`,kind:'asset',asset:a,what:a.name,who:a.owner||a.description,total:num(a.price),paid:assetPaid(a),remaining,payments,allPayments,nextDate:payments[0]?.date||'',nextAmount:payments[0]?.amount||remaining,status:a.status||'Покупаю'})});state.debts.forEach(d=>{const remaining=manualDebtRemaining(d);if(remaining>0){const scale=!d.currency||d.currency==='RUB'?1:(num(d.fxRate)>0?num(d.fxRate):1);const rubOf=n=>roundMoney(num(n)*scale);items.push({id:d.id,kind:'manual',debt:d,what:d.what,who:d.who,total:rubOf(d.total),paid:rubOf(d.paid),remaining:rubOf(remaining),payments:[],allPayments:d.nextDate?[{id:`${d.id}-next`,date:d.nextDate,amount:Math.min(rubOf(d.nextAmount),rubOf(remaining)),status:'Предстоит'}]:[],nextDate:d.nextDate,nextAmount:Math.min(rubOf(d.nextAmount),rubOf(remaining)),status:'Предстоит'})}});return items}
function totals(){const cash=state.accounts.reduce((s,x)=>s+accountRub(x),0), deposits=state.deposits.reduce((s,x)=>x.closed?s:s+num(x.current),0), assets=state.assets.reduce((s,x)=>s+num(x.value),0), debts=obligations().reduce((s,x)=>s+x.remaining,0);return {cash,deposits,assets,debts,net:cash+deposits+assets-debts}}
function escText(value){return String(value==null?'':value).replace(/[&<>"']/g,function(ch){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]})}
function fullDate(value){if(!value)return '—';const date=new Date(value+'T12:00:00');if(Number.isNaN(date.getTime()))return '—';return String(date.getDate()).padStart(2,'0')+'.'+String(date.getMonth()+1).padStart(2,'0')+'.'+date.getFullYear()}
function businessDaysBetween(fromIso,toIso){if(!fromIso||!toIso)return null;const start=new Date(fromIso+'T12:00:00'),target=new Date(toIso+'T12:00:00');if(Number.isNaN(start.getTime())||Number.isNaN(target.getTime()))return null;if(target<start)return -1;let count=0;const cursor=new Date(start);cursor.setDate(cursor.getDate()+1);while(cursor<=target){const day=cursor.getDay();if(day!==0&&day!==6)count+=1;cursor.setDate(cursor.getDate()+1)}return count}
function businessDaysUntil(date){return businessDaysBetween(isoDate(today),date)}
function workLeftText(work){if(work==null||work<=0)return 'Осталось меньше одного рабочего дня';const n=work%100,n1=n%10;if(n>10&&n<20)return 'Осталось '+work+' рабочих дней';if(n1===1)return 'Остался '+work+' рабочий день';if(n1>=2&&n1<=4)return 'Осталось '+work+' рабочих дня';return 'Осталось '+work+' рабочих дней'}
function currentFx(asset,currency){if(!currency||currency==='RUB')return 1;if(asset&&(asset.currency||'RUB')===currency&&num(asset.currentRate)>0)return num(asset.currentRate);if(typeof liveRate==='function'){const rate=num(liveRate(currency));if(rate>0)return rate}return 0}
function moneyInCurrency(amount,currency){if(!currency||currency==='RUB')return rub(amount);if(typeof moneyOriginal==='function')return moneyOriginal(amount,currency);const formatted=new Intl.NumberFormat('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2}).format(roundMoney(amount));if(currency==='USD')return formatted+' $';if(currency==='EUR')return formatted+' €';return formatted+' '+currency}
function depositIdentity(deposit){return [deposit.bank||'Вклад',deposit.owner||'',deposit.last4?'•••• '+deposit.last4:''].filter(Boolean).join(' · ')}
function attentionFor(date,kind,done){if(done||!date||(kind!=='payment'&&kind!=='end'))return {level:'',lines:[]};const days=daysFromNow(date),work=businessDaysUntil(date),full=fullDate(date);if(days<0){if(kind==='end')return {level:'overdue',lines:['Окончание '+full,'Дата уже прошла']};return {level:'overdue',lines:['Дата платежа '+full,'Платёж не отмечен как оплаченный']}}if(days===0){if(kind==='end')return {level:'today',lines:['Окончание '+full]};return {level:'today',lines:['Оплатить '+full]}}if(work!=null&&work<=2)return {level:'soon',lines:[kind==='end'?'Окончание '+full:'Оплатить '+full,workLeftText(work)]};return {level:'',lines:[kind==='end'?'Окончание '+full:'Дата '+full]}}
function labelFor(kind,attention,done){if(done){if(kind==='rent')return 'Поступление аренды';if(kind==='income')return 'Поступление процентов';if(kind==='end')return 'Окончание вклада';return 'Платёж'}if(attention==='overdue')return kind==='end'?'Срок вклада прошёл':'ПРОСРОЧЕНО';if(attention==='today')return kind==='end'?'Вклад заканчивается сегодня':'Оплатить сегодня';if(attention==='soon')return kind==='end'?'Скоро заканчивается вклад':'Скоро платёж';if(kind==='end')return 'Окончание вклада';if(kind==='income')return 'Поступление процентов';if(kind==='rent')return 'Поступление аренды';return 'Платёж'}
function needsAttention(event){if(!event||event.done)return false;if(event.kind!=='payment'&&event.kind!=='end')return false;return event.attention==='soon'||event.attention==='today'||event.attention==='overdue'}
function homeEvents(){const all=eventList().filter(function(event){return event&&event.date});const hot=all.filter(needsAttention).sort(function(a,b){return String(a.date).localeCompare(String(b.date))});const next=all.filter(function(event){return !event.done&&!needsAttention(event)&&daysFromNow(event.date)>=0}).sort(function(a,b){return String(a.date).localeCompare(String(b.date))});const picked=[],seen={};hot.concat(next).forEach(function(event){if(picked.length>=5||seen[event.id])return;seen[event.id]=true;picked.push(event)});return picked}
