function calendarEventCard(event){const primary=event.primary||event.sub||event.title||'';const secondary=event.secondary&&event.secondary!==primary?'<span class="cal-sub">'+escText(event.secondary)+'</span>':'';const amount=event.amountText||(event.amount?rub(Math.abs(num(event.amount))):'—');const hint=event.rubHint?'<small>'+escText(event.rubHint)+'</small>':'';return '<div class="calendar-event '+calendarTone(event)+'" data-event-id="'+escText(event.id||'')+'" onclick="openCalendarEvent(this.dataset.eventId)"><strong>'+escText(event.label||event.title||'')+'</strong><span>'+escText(primary)+'</span>'+secondary+'<b>'+escText(amount)+'</b>'+hint+'</div>'}
