function daysFromNow(d){return Math.ceil((new Date(d+'T12:00:00')-new Date(isoDate(today)+'T12:00:00'))/86400000)}
function eventTag(e){const days=daysFromNow(e.date);if(e.status==='Получено'||e.status==='Оплачено')return '<span class="tag tag-green">Выполнено</span>';if(days<0)return '<span class="tag tag-red">Просрочено</span>';if(days<=7)return '<span class="tag tag-yellow">Скоро</span>';return '<span class="tag tag-blue">Предстоит</span>'}
function metric(label,value,sub,cls='',formatter=rub){return `<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${formatter(value)}</div><div class="metric-sub ${cls}">${sub}</div></div>`}
function dashboard(){const t=totals(), events=homeEvents(), attention=eventList().filter(e=>e.status!=='Получено'&&e.status!=='Оплачено'&&daysFromNow(e.date)<=7), obligationCount=obligations().length, growth=monthGrowth();return `<div class="view-wrap"><div class="section-heading"><div><p class="eyebrow">ОБЗОР СОСТОЯНИЯ</p><h2>Ваши финансы сегодня</h2></div><button class="primary-button" onclick="openForm('quick')">＋ Добавить запись</button></div><div class="metrics">${metric('Деньги на счетах и картах',t.cash,'Свободные деньги')} ${metric('Вклады',t.deposits,`${state.deposits.length} ${plural(state.deposits.length,'вклад','вклада','вкладов')}`)} ${metric('Доход по вкладам',state.deposits.reduce((s,x)=>s+num(x.received),0),'Получено по вкладам','positive')} ${metric('Ожидается в '+monthInName(),expectedThisMonth(),currentMonthRangeText(),'warning')}</div><div class="metrics" style="margin-top:14px">${metric('Имущество',t.assets,'Оценочная стоимость')} ${metric('Обязательства',t.debts,`Остаток по ${obligationCount} ${plural(obligationCount,'обязательству','обязательствам','обязательствам')}`,'danger')} ${metric('Чистый капитал',t.net,growth&&growth.pct!=null?`За месяц · ${growth.pct>=0?'+':''}${growth.pct.toFixed(1).replace('.',',')}%`:'Снимка ещё нет','positive')} ${metric('Изменение за год',0,'Снимка ещё нет','',()=>'—')}</div><div class="dashboard-grid"><div class="panel"><div class="panel-head"><div><h3>Ближайшие события</h3><span>Что важно не пропустить</span></div><button class="ghost-button" onclick="setView('calendar')">Весь календарь →</button></div><div class="events">${events.length?events.map(e=>`<div class="event"><div class="event-date">${dateText(e.date)}</div><div class="event-main"><span class="event-icon">${e.type==='payment'?'₽':e.type==='end'?'◷':'↗'}</span><div>${e.title}<small>${e.sub}</small></div></div><div><div class="event-amount ${e.amount<0?'danger':''}">${e.amount?rub(Math.abs(e.amount)):''}</div>${eventTag(e)}</div></div>`).join(''):'<div class="empty">Событий пока нет</div>'}</div></div><div class="panel"><div class="panel-head"><div><h3>Как меняется капитал</h3><span>По сохранённым снимкам</span></div><button class="ghost-button" onclick="setView('history')">Подробнее</button></div><div class="mini-bars">${capitalBars()}</div><div class="capital-legend"><span><i class="dot"></i> Чистый капитал</span><span>${growth&&growth.pct!=null?`${growth.pct>=0?'+':''}${growth.pct.toFixed(1).replace('.',',')}% к прошлому снимку`:'Снимка ещё нет'}</span></div></div></div><div class="dashboard-grid"><div class="panel"><div class="panel-head"><div><h3>Требует внимания</h3><span>Проверки на сегодня</span></div><span class="tag tag-yellow">${attention.length} ${plural(attention.length,'событие','события','событий')}</span></div><div class="notice-list">${attention.length?attention.slice(0,4).map(e=>`<div class="notice"><span class="notice-icon">!</span><div><strong>${daysFromNow(e.date)<0?'Просрочено: ':''}${e.title}</strong>${e.status==='Ожидается'?'Проверьте поступление процентов · ':''}${dateText(e.date)} ${e.amount?`· ${rub(Math.abs(e.amount))}`:''}</div></div>`).join(''):'<div class="empty">Всё под контролем</div>'}</div></div><div class="panel"><div class="panel-head"><div><h3>Структура капитала</h3><span>Текущий баланс</span></div></div><div class="stat-row"><span>Счета и карты</span><strong>${rub(t.cash)}</strong></div><div class="stat-row"><span>Вклады</span><strong>${rub(t.deposits)}</strong></div><div class="stat-row"><span>Имущество</span><strong>${rub(t.assets)}</strong></div><div class="stat-row"><span>Обязательства</span><strong class="danger">− ${rub(t.debts)}</strong></div></div></div></div>`}
function plural(n,a,b,c){return n%10===1&&n%100!==11?a:n%10>=2&&n%10<=4&&(n%100<10||n%100>=20)?b:c}
function capitalSnapshots(){return (Array.isArray(state.history)?state.history:[]).filter(h=>h&&h.date)}
function monthGrowth(){const snaps=capitalSnapshots();if(snaps.length<2)return null;const prev=num(snaps[snaps.length-2].net),last=num(snaps[snaps.length-1].net),delta=last-prev;return {delta,pct:prev?delta/prev*100:null}}
function growthCaption(formatMoney){const growth=monthGrowth();if(!growth)return 'Снимка ещё нет';const pct=growth.pct==null?'':` · ${growth.pct>=0?'+':''}${growth.pct.toFixed(1).replace('.',',')}%`;return `↗ <b class="teal">${growth.delta>=0?'+':''}${formatMoney(growth.delta)}${pct}</b> рост за месяц`}
function capitalBars(){const snaps=capitalSnapshots().slice(-6);if(snaps.length<2)return '<div class="empty">Снимка ещё нет</div>';const values=snaps.map(h=>num(h.net)),min=Math.min(...values),range=(Math.max(...values)-min)||1;return snaps.map((h,i)=>{const height=18+((num(h.net)-min)/range)*82;return `<div class="bar-col"><div class="bar ${i===snaps.length-1?'current':''}" style="height:${height}%"></div><label>${dateText(h.date)}</label></div>`}).join('')}
function portfolioRate(){const base=state.deposits.reduce((s,x)=>x.closed?s:s+num(x.current),0);if(!base)return null;return state.deposits.reduce((s,x)=>x.closed?s:s+num(x.rate)*num(x.current),0)/base}
function emptyCabinet(){return {accounts:[],deposits:[],assets:[],debts:[],history:[],transactions:[]}}
function listView(type,title,desc,button,columns,rows){return `<div class="view-wrap"><div class="section-heading"><div><p class="eyebrow">УПРАВЛЕНИЕ ДАННЫМИ</p><h2>${title}</h2><p>${desc}</p></div><button class="primary-button" onclick="openForm('${type}')">＋ ${button}</button></div><div class="panel"><div class="table-wrap"><table class="data-table"><thead><tr>${columns.map(x=>`<th>${x}</th>`).join('')}<th></th></tr></thead><tbody>${rows||`<tr><td colspan="${columns.length+1}"><div class="empty"><div class="empty-icon">＋</div>Нет записей. Добавьте первую запись.</div></td></tr>`}</tbody></table></div></div></div>`}
function actions(type,id){return `<div class="button-row"><button class="ghost-button" onclick="openForm('${type}','${id}')">Изменить</button><button class="ghost-button" onclick="removeItem('${type}','${id}')">Удалить</button></div>`}
function deposits(){const rows=state.deposits.map(d=>`<tr><td><strong>${d.bank}</strong><br><span class="muted">•••• ${d.last4}</span></td><td>${d.name}</td><td>${d.owner||'—'}</td><td>${rub(d.initial)}</td><td><strong>${rub(d.current)}</strong><br><span class="positive">${rateText(d.rate)}% годовых</span></td><td>${rubPrecise(d.received)}</td><td>${rub(d.status==='Получено'?0:d.expected)}</td><td>${dateText(d.nextDate)}<br>${d.status==='Получено'?'<span class="tag tag-green">Получено</span>':'<span class="tag tag-yellow">Проверьте поступление</span>'}</td><td>${actions('deposit',d.id)}</td></tr>`).join('');return listView('deposit','Вклады','Суммы, ставки и контроль фактических начислений','Добавить вклад',['Банк','Вклад','На кого оформлен','Вложено','Текущая сумма','Получено','Ожидается','Следующая выплата'],rows)}
function accounts(){const rows=state.accounts.map(a=>`<tr><td><strong>${a.bank}</strong><br><span class="muted">${a.type} · •••• ${a.last4}</span></td><td>${a.owner}</td><td><strong>${accountMoney(a)}</strong></td><td>${a.rate?`${rateText(a.rate)}%<br><span class="muted">${dateText(a.nextDate)}</span>`:'—'}</td><td>${actions('account',a.id)}</td></tr>`).join('');return listView('account','Карты и счета',`Всего по всем банкам: ${rub(state.accounts.reduce((s,x)=>s+accountRub(x),0))}`,'Добавить счёт',['Банк и тип','Владелец','Остаток','Процент на остаток'],rows)}
function assets(){const rows=state.assets.map(a=>`<tr><td><strong>${a.name}</strong><br><span class="muted">${a.category} · ${a.description}</span></td><td>${rub(a.price)}</td><td>${rub(assetPaid(a))}<br><span class="muted">осталось ${rub(assetRemaining(a))}</span></td><td><strong>${rub(a.value)}</strong></td><td>${a.owner}</td><td>${actions('asset',a.id)}</td></tr>`).join('');return listView('asset','Имущество',`Оценочная стоимость: ${rub(state.assets.reduce((s,x)=>s+num(x.value),0))}`,'Добавить объект',['Объект','Цена покупки','Оплачено','Оценка сейчас','Собственник'],rows)}
function debts(){const items=obligations(),cash=state.accounts.reduce((s,x)=>s+accountRub(x),0),total=items.reduce((s,x)=>s+x.remaining,0),need=total-cash,nearest=items.flatMap(o=>(o.allPayments||[]).map(p=>({...p,what:o.what}))).sort((a,b)=>a.date.localeCompare(b.date))[0];const summary=`<div class="obligation-summary"><div class="obligation-summary-item"><span>Доступно на картах и счетах</span><strong>${rub(cash)}</strong></div><div class="obligation-summary-item"><span>Всего обязательств</span><strong>${rub(total)}</strong></div><div class="obligation-summary-item"><span>Ближайший платёж</span><strong>${nearest?rub(nearest.amount):'—'}</strong><small>${nearest?`${dateText(nearest.date)} · ${nearest.what}`:'Платежей нет'}</small></div><div class="obligation-summary-item ${need>0?'summary-danger':'summary-good'}"><span>Нужно обеспечить</span><strong>${need>0?`Нужно обеспечить ещё: ${rub(need)}`:'Средств достаточно'}</strong></div></div>`;const cards=items.map(o=>{const all=o.allPayments||[],visible=all.slice(0,3),hidden=all.length>3?all.slice(3):[],stages=list=>list.map(p=>`<div class="payment-stage ${p.status==='Оплачено'?'stage-paid':''} ${p.status!=='Оплачено'&&p.date===o.nextDate?'stage-next':''}"><strong>${p.status==='Оплачено'?'✓ ':''}${rub(p.amount)}</strong><span>${p.status==='Оплачено'?'Оплачено':dateText(p.date)}</span>${weekendNotice(p.date)}</div>`).join('');return `<article class="obligation-card"><div class="obligation-card-head"><div><p class="eyebrow">${o.kind==='asset'?'ИМУЩЕСТВО':'РУЧНОЕ ОБЯЗАТЕЛЬСТВО'}</p><h3>${o.what}</h3><span>${o.who}</span></div><div class="obligation-actions">${o.kind==='manual'?actions('debt',o.debt.id):'<span class="tag tag-blue">Из имущества</span>'}</div></div><div class="obligation-totals"><div><span>Стоимость</span><strong>${rub(o.total)}</strong></div><div><span>Оплачено</span><strong>${rub(o.paid)}</strong></div><div><span>Осталось</span><strong class="danger">${rub(o.remaining)}</strong></div></div><div class="payment-stages">${stages(visible)||'<span class="muted">Будущие платежи не добавлены</span>'}</div>${hidden.length?`<div class="payment-extra" id="payments-${o.id}">${stages(hidden)}</div><button class="ghost-button payment-toggle" onclick="togglePayments('${o.id}',this)">Все платежи</button>`:''}</article>`}).join('');return `<div class="view-wrap"><div class="section-heading"><div><p class="eyebrow">УПРАВЛЕНИЕ ДАННЫМИ</p><h2>Обязательства</h2><p>Платежи имущества и отдельные будущие долги</p></div><button class="primary-button" onclick="openForm('debt')">＋ Добавить обязательство</button></div>${summary}<div class="obligation-cards">${cards||'<div class="panel empty">Обязательств пока нет</div>'}</div></div>`}
function calendar(){const y=calendarMonth.getFullYear(),m=calendarMonth.getMonth(),first=new Date(y,m,1),last=new Date(y,m+1,0),start=(first.getDay()+6)%7,days=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'],events=eventList();let cells=days.map(d=>`<div class="calendar-day-name">${d}</div>`).join('');for(let i=0;i<start;i++)cells+=`<div class="calendar-cell muted"></div>`;for(let d=1;d<=last.getDate();d++){const date=isoDate(new Date(y,m,d)),ev=events.filter(x=>x.date===date),isToday=date===isoDate(today),visible=ev.slice(0,3),hidden=ev.slice(3),eventMarkup=e=>calendarEventCard(e);cells+=`<div class="calendar-cell ${isToday?'today-cell':''}"><div class="day-number">${d}</div><div class="calendar-events">${visible.map(eventMarkup).join('')}</div>${hidden.length?`<button class="calendar-more" onclick="this.previousElementSibling.classList.toggle('is-open');this.textContent=this.previousElementSibling.classList.contains('is-open')?'Скрыть':'＋ ещё ${hidden.length}'">＋ ещё ${hidden.length}</button><div class="calendar-events calendar-events-extra">${hidden.map(eventMarkup).join('')}</div>`:''}</div>`}return `<div class="view-wrap"><div class="section-heading"><div><p class="eyebrow">ПЛАНИРОВАНИЕ</p><h2>Финансовый календарь</h2><p>Зелёным — поступления · красным — платежи и окончания вкладов</p></div><button class="primary-button" onclick="openForm('debt')">＋ Добавить событие</button></div><div class="panel"><div class="panel-head"><div class="calendar-controls"><button onclick="changeMonth(-1)">←</button><div class="calendar-title">${calendarMonth.toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</div><button onclick="changeMonth(1)">→</button></div><span>${events.length} событий</span></div><div class="calendar-grid">${cells}</div></div></div>`}
function income(){const rows=state.deposits.map(d=>`<tr><td><strong>${d.bank}</strong></td><td>${d.name}</td><td>${rub(d.expected)}</td><td>${rubPrecise(d.received)}</td><td class="${d.received<d.expected?'danger':'positive'}">${d.received>=d.expected?'—':'− '+rubPrecise(d.expected-d.received)}</td><td>${d.status==='Получено'?'<span class="tag tag-green">Получено</span>':'<button class="ghost-button" onclick="markReceived(\''+d.id+'\')">Отметить получение</button>'}</td></tr>`).join('');return `<div class="view-wrap"><div class="section-heading"><div><p class="eyebrow">АНАЛИТИКА</p><h2>Доход по процентам</h2><p>План-факт по всем вкладам, без автоматического зачёта получения</p></div><div class="button-row"><span class="tag tag-green">Месяц</span><span class="tag">Год</span><span class="tag">Весь период</span></div></div><div class="metrics">${metric('План процентов',state.deposits.reduce((s,x)=>s+x.expected,0),'За текущий период')} ${metric('Получено фактически',state.deposits.reduce((s,x)=>s+x.received,0),'Подтверждено вручную','positive',rubPrecise)} ${metric('Разница',state.deposits.reduce((s,x)=>s+Math.min(0,x.received-x.expected),0),'Требует проверки','danger',rubPrecise)} ${metric('Доходность портфеля',portfolioRate()||0,'Средняя ставка','positive',v=>portfolioRate()==null?'—':new Intl.NumberFormat('ru-RU',{minimumFractionDigits:0,maximumFractionDigits:2}).format(v)+'%')}</div><div class="panel" style="margin-top:18px"><div class="table-wrap"><table class="data-table"><thead><tr><th>Банк</th><th>Вклад</th><th>План процентов</th><th>Получено</th><th>Разница</th><th>Статус</th></tr></thead><tbody>${rows}</tbody></table></div></div></div>`}
function forecast(){const t=totals();return `<div class="view-wrap"><div class="section-heading"><div><p class="eyebrow">ПЛАНИРОВАНИЕ ДЕНЕГ</p><h2>Финансовый прогноз</h2><p>Оценка будущих потоков на основе ваших записей</p></div></div><div class="forecast-cards">${[30,90,180,365].map((days,i)=>{const until=new Date(today.getFullYear(),today.getMonth(),today.getDate()+days),untilKey=isoDate(until),todayKey=isoDate(today),depositIncoming=state.deposits.reduce((s,x)=>x.closed||x.status==='Получено'||!x.nextDate||x.nextDate<todayKey||x.nextDate>untilKey?s:s+num(x.expected),0),rentIncoming=state.assets.reduce((s,asset)=>s+((asset.rent&&asset.rent.payments)||[]).reduce((part,payment)=>payment.status==='Получено'||!payment.date||payment.date<todayKey||payment.date>untilKey?part:part+num(payment.amount),0)+(asset.parts||[]).reduce((partSum,room)=>room.usage==='Сдаётся в аренду'?partSum+(room.rentPayments||[]).reduce((paySum,payment)=>payment.status==='Получено'||!payment.date||payment.date<todayKey||payment.date>untilKey?paySum:paySum+num(payment.amount),0):partSum,0),0),incoming=depositIncoming+rentIncoming,outgoing=eventList().filter(e=>e.type==='payment'&&e.date&&e.date>=todayKey&&e.date<=untilKey).reduce((s,e)=>s+Math.abs(e.amount),0),diff=incoming-outgoing;return `<div class="forecast-card"><h3>${days===30?'30 дней':days===90?'3 месяца':days===180?'6 месяцев':'год'}</h3><div class="forecast-total ${diff<0?'danger':'positive'}">${diff>=0?'+':''}${rub(diff)}</div><div class="forecast-line"><span>Ожидается</span><strong class="positive">+ ${rub(incoming)}</strong></div><div class="forecast-line"><span>Нужно оплатить</span><strong class="danger">− ${rub(outgoing)}</strong></div><div class="progress"><i style="width:${Math.min(100,outgoing?incoming/outgoing*100:(incoming?100:0))}%"></i></div></div>`}).join('')}</div><div class="panel" style="margin-top:18px"><div class="panel-head"><div><h3>Свободные деньги</h3><span>Текущий резерв против ближайших обязательств</span></div><strong>${rub(t.cash)}</strong></div><div class="progress" style="height:12px"><i style="width:${Math.min(100,t.cash/(t.debts||1)*100)}%"></i></div></div></div>`}
function history(){const t=totals();return `<div class="view-wrap"><div class="section-heading"><div><p class="eyebrow">ДИНАМИКА</p><h2>История капитала</h2><p>Снимки состава капитала по месяцам</p></div><button class="primary-button" onclick="takeSnapshot()">＋ Сохранить снимок</button></div><div class="panel"><div class="mini-bars" style="height:260px">${capitalBars()}</div><div class="capital-legend"><span><i class="dot"></i> Чистый капитал · ${rub(t.net)}</span></div></div><div class="panel" style="margin-top:18px"><h3>Сохранённые снимки</h3>${state.history.length?state.history.map(h=>`<div class="stat-row"><span>${dateText(h.date)}</span><strong>${rub(h.net)}</strong></div>`).join(''):'<div class="empty">Снимка ещё нет</div>'}</div></div>`}
function settings(){return `<div class="view-wrap"><div class="section-heading"><div><p class="eyebrow">КОНФИДЕНЦИАЛЬНОСТЬ</p><h2>Настройки</h2><p>Данные кабинета хранятся локально в браузере</p></div></div><div class="panel settings-box"><div class="security-callout"><strong>Ваши банковские данные защищены архитектурой приложения.</strong><br>Кабинет не хранит PIN-коды, CVV/CVC, пароли и полные номера карт.</div><h3>Резервная копия</h3><p class="muted">Скачайте файл с данными или восстановите ранее сохранённую копию.</p><div class="button-row" style="margin:18px 0 28px"><button class="primary-button" onclick="exportData()">↓ Экспортировать данные</button><button class="ghost-button" onclick="document.getElementById('import-file').click()">↑ Восстановить из файла</button><input id="import-file" type="file" accept="application/json" hidden onchange="importData(event)"></div><h3>Данные</h3><div class="stat-row"><span>Записей в кабинете</span><strong>${state.accounts.length+state.deposits.length+state.assets.length+state.debts.length}</strong></div><div class="stat-row"><span>Хранилище</span><strong>Локально в браузере</strong></div><button class="ghost-button" style="margin-top:18px;color:var(--red)" onclick="clearData()">Очистить все данные</button></div></div>`}
function render(){const views={dashboard,deposits,accounts,assets,debts,calendar,income,forecast,history,settings};document.getElementById('app-view').innerHTML=views[activeView]();document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===activeView));document.getElementById('page-title').textContent={dashboard:'Добрый день',deposits:'Вклады',accounts:'Карты и счета',assets:'Имущество',debts:'Обязательства',calendar:'Календарь',income:'Доход по процентам',forecast:'Прогноз',history:'История капитала',settings:'Настройки'}[activeView];document.getElementById('deposit-count').textContent=state.deposits.filter(d=>!d.closed).length;document.getElementById('debt-count').textContent=obligations().length;document.getElementById('today-label').textContent=dateText(isoDate(today));if(typeof updateCalendarAlert==='function')updateCalendarAlert()}
function setView(v){activeView=v;render()}window.setView=setView;function changeMonth(n){calendarMonth.setMonth(calendarMonth.getMonth()+n);render()}window.changeMonth=changeMonth;
const schemas={deposit:{title:'Новый вклад',fields:[['bank','Банк'],['name','Название вклада'],['owner','На кого оформлен'],['last4','Последние 4 цифры'],['current','Сумма вклада','number'],['rate','Ставка годовых, %','number'],['open','Дата открытия','date'],['end','Дата окончания','date'],['nextDate','Следующее начисление','date'],['expected','Ожидается процентов','number'],['received','Получено процентов','number'],['coverObligations','Учитывать для покрытия обязательств']]},account:{title:'Новый счёт или карта',fields:[['bank','Банк'],['type','Тип'],['owner','Владелец'],['last4','Последние 4 цифры'],['balance','Текущий остаток','number'],['rate','Процентная ставка, %','number'],['nextDate','Дата следующего начисления','date'],['expected','Ожидаемая сумма процентов','number'],['comment','Комментарий'],['coverObligations','Учитывать для покрытия обязательств']]},asset:{title:'Новый объект имущества',fields:[['name','Название объекта'],['type','Тип объекта'],['description','Адрес или описание'],['owner','Собственник'],['ownershipStatus','Статус владения'],['value','Текущая оценочная стоимость','number'],['valueCurrency','Валюта оценки'],['acquisition','Дата приобретения','date'],['comment','Комментарий'],['price','Стоимость по договору','number'],['paid','Оплачено','number']]},debt:{title:'Новое обязательство',fields:[['who','Кому должна'],['what','За что'],['total','Общая сумма','number'],['paid','Сколько оплачено','number'],['nextDate','Дата следующего платежа','date'],['nextAmount','Сумма следующего платежа','number'],['end','Конечная дата','date'],['comment','Комментарий']]}};
function bindPaymentDate(input){const update=()=>{input.parentElement.querySelectorAll('.weekend-warning').forEach(node=>node.remove());input.classList.toggle('weekend-date',isWeekend(input.value));if(isWeekend(input.value))input.insertAdjacentHTML('afterend',weekendNotice(input.value))};input.addEventListener('change',update);update()}
function togglePayments(id,button){const extra=document.getElementById(`payments-${id}`);if(!extra)return;const open=extra.classList.toggle('is-open');button.textContent=open?'Скрыть платежи':'Все платежи'}window.togglePayments=togglePayments;
function choiceSelect(name,options,current){return `<select name="${name}">${options.map(option=>`<option ${String(option)===String(current)?'selected':''}>${option}</option>`).join('')}</select>`}
function accountTypeChoice(value){const text=String(value||'').trim().toLowerCase().replace(/ё/g,'е');if(text==='банковская карта'||text==='карта')return 'Банковская карта';if(text==='текущий счет')return 'Текущий счёт';if(text==='накопительный счет')return 'Накопительный счёт';if(text==='другое')return 'Другое';return value?'Другое':'Банковская карта'}
function syncAccountForm(form){const select=form&&form.querySelector('[name="type"]');if(!select)return;const apply=()=>{const savings=select.value==='Накопительный счёт';form.querySelectorAll('.account-savings-only').forEach(node=>{node.hidden=!savings})};select.addEventListener('change',apply);apply()}
function openForm(type,id){if(type==='quick')type='deposit';const s=schemas[type],item=(state[type+'s']||[]).find(x=>x.id===id)||{};const fields=s.fields.map(([key,label,input])=>{const isRate=key==='rate'||input==='rate',isMoney=!isRate&&input==='number',inputType=isMoney||isRate?'text':input||'text',inputAttrs=isRate||isMoney?'inputmode="decimal" autocomplete="off"':'';const rawValue=type==='asset'&&key==='paid'&&item.paidBase!==undefined?item.paidBase:(item[key]??'');const fieldValue=isMoney&&rawValue!==''&&rawValue!=null?formatMoneyInput(rawValue):rawValue;const control=key==='coverObligations'?choiceSelect(key,['Да','Нет'],item.coverObligations===false?'Нет':'Да'):key==='type'?(type==='account'?choiceSelect(key,['Банковская карта','Текущий счёт','Накопительный счёт','Другое'],accountTypeChoice(item.type)):choiceSelect(key,['Квартира','Дом','Территория или имущественный комплекс','Склад','Коммерческое помещение','Земельный участок','Автомобиль','Другое'],item.type||item.category||'Другое')):key==='ownershipStatus'?choiceSelect(key,['В собственности','Покупается','Совместная собственность','Другое'],item.ownershipStatus||'В собственности'):key==='valueCurrency'?`<select name="valueCurrency" data-currency-catalog="1"><option selected>${item.valueCurrency||item.currency||'RUB'}</option></select>`:key==='status'?`<select name="status"><option ${item.status==='Покупаю'?'selected':''}>Покупаю</option><option ${item.status==='Оплачено'?'selected':''}>Оплачено</option><option ${item.status==='В собственности'?'selected':''}>В собственности</option></select>`:`<input name="${key}" type="${inputType}" ${inputAttrs} value="${fieldValue}" ${key==='last4'?'maxlength="4"':''}>`;return `<div class="form-field${key==='price'||key==='paid'?' purchase-only':''}${type==='account'&&(key==='rate'||key==='nextDate'||key==='expected')?' account-savings-only':''}"><label>${label}</label>${control}</div>`}).join('');const payments=type==='asset'?assetPayments(item):[];const paymentRows=payments.map(p=>`<div class="payment-row"><input name="payment-date" type="date" value="${p.date||''}"><input name="payment-amount" type="text" inputmode="decimal" value="${p.amount==null||p.amount===''?'':formatMoneyInput(p.amount)}"><select name="payment-status"><option ${p.status==='Предстоит'?'selected':''}>Предстоит</option><option ${p.status==='Оплачено'?'selected':''}>Оплачено</option></select><button type="button" class="ghost-button" onclick="this.parentElement.remove()">Удалить</button></div>`).join('');const paymentBlock=type==='asset'?`<div class="payment-section"><div class="payment-section-head"><strong>График платежей</strong><button type="button" class="ghost-button" onclick="addPaymentRow()">＋ Добавить платёж</button></div><div id="payment-rows">${paymentRows}</div></div>`:'';document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal${type==='asset'?' modal-asset':''}"><div class="modal-header"><h2>${id?'Изменить':'Добавить'} ${s.title.replace('Новый ','').toLowerCase()}</h2><button class="close" onclick="closeModal()">×</button></div><form id="record-form"><div class="modal-body"><div class="form-grid">${fields}</div>${paymentBlock}</div><div class="modal-footer"><button type="button" class="ghost-button" onclick="closeModal()">Отмена</button><button class="primary-button">Сохранить</button></div></form></div></div>`;if(type==='account')syncAccountForm(document.getElementById('record-form'));document.querySelectorAll('#payment-rows [name="payment-date"]').forEach(bindPaymentDate);document.getElementById('record-form').onsubmit=e=>{e.preventDefault();const obj=Object.fromEntries(new FormData(e.target));s.fields.forEach(([key,,input])=>{if(key==='coverObligations')obj[key]=obj[key]!=='Нет';else if(input==='number'||input==='rate'||key==='rate')obj[key]=num(obj[key])});obj.id=id||uid();if(type==='deposit'){obj.status=num(obj.received)>=num(obj.expected)?'Получено':'Не получено'}if(type==='asset'){obj.paidBase=num(obj.paid);obj.status=obj.ownershipStatus==='Покупается'?'Покупаю':'В собственности';obj.category=obj.type||obj.category||'';obj.purchase=obj.acquisition||obj.purchase||'';const previous=id?state.assets.find(x=>x.id===id):null;obj.payments=[...document.querySelectorAll('#payment-rows .payment-row')].map(row=>{const existingId=row.querySelector('[name="payment-id"]');return {id:(existingId&&existingId.value)||uid(),date:row.querySelector('[name="payment-date"]').value,amount:num(row.querySelector('[name="payment-amount"]').value),status:row.querySelector('[name="payment-status"]').value}}).filter(p=>p.date&&p.amount>0);if(previous){obj.parts=previous.parts||[];obj.rent=previous.rent;obj.photos=previous.photos;obj.photo=previous.photo;obj.calcType=previous.calcType;obj.rateMode=previous.rateMode;obj.initialRate=previous.initialRate;obj.currentRate=previous.currentRate;obj.paidRub=previous.paidRub;obj.rateHistory=previous.rateHistory;obj.statusHistory=previous.statusHistory;obj.usage=previous.usage;obj.usageStatus=previous.usageStatus}obj.paid=assetPaid(obj)}if(type==='debt')obj.paid=num(obj.paid);if(type==='account'&&obj.type!=='Накопительный счёт'){obj.rate=0;obj.nextDate='';obj.expected=0}const arr=state[type+'s'];const ix=arr.findIndex(x=>x.id===obj.id);if(ix>=0)arr[ix]=obj;else arr.push(obj);save();closeModal();render()}}
function addPaymentRow(){const container=document.getElementById('payment-rows');if(!container)return;container.insertAdjacentHTML('beforeend','<div class="payment-row"><input name="payment-date" type="date"><input name="payment-amount" type="text" inputmode="decimal"><select name="payment-status"><option selected>Предстоит</option><option>Оплачено</option></select><button type="button" class="ghost-button" onclick="this.parentElement.remove()">Удалить</button></div>');bindPaymentDate(container.lastElementChild.querySelector('[name="payment-date"]'))}window.addPaymentRow=addPaymentRow;
window.openForm=openForm;function closeModal(){document.getElementById('modal-root').innerHTML=''}window.closeModal=closeModal;
function removeItem(type,id){if(confirm('Удалить эту запись?')){state[type+'s']=state[type+'s'].filter(x=>x.id!==id);save();render()}}window.removeItem=removeItem;
function markReceived(id){const d=state.deposits.find(x=>x.id===id);if(d){d.received=d.expected;d.status='Получено';save();render()}}window.markReceived=markReceived;
function takeSnapshot(){state.history.push({...totals(),date:isoDate(today)});save();render()}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`финансы-резерв-${isoDate(today)}.json`;a.click();URL.revokeObjectURL(a.href)}window.exportData=exportData;
function importData(e){const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(!data.accounts||!data.deposits)throw Error();state=normalizeState(data);save();render();alert('Данные восстановлены')}catch{alert('Не удалось прочитать резервную копию')}};reader.readAsText(file)}window.importData=importData;
function clearData(){if(confirm('Удалить все финансовые данные? Это действие нельзя отменить.')){state=emptyCabinet();save();render()}}window.clearData=clearData;
const baseDepositsView=deposits;deposits=function(){return baseDepositsView()+depositMonthForecast()};
document.getElementById('main-nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)setView(b.dataset.view)});document.querySelector('.top-actions').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)setView(b.dataset.view)});render();
const moneyFieldNames={initial:1,current:1,expected:1,received:1,balance:1,value:1,price:1,paid:1,total:1,nextAmount:1,'payment-amount':1,'series-amount':1,paidRub:1,'part-rent':1,opening:1,amount:1,paidAmount:1,rubActual:1,rentAmount:1,rentDeposit:1,allocationAmount:1,closeInterest:1,'fx-pay-amount':1,'fx-pay-rub':1};
function isMoneyField(el){return !!(el&&el.tagName==='INPUT'&&moneyFieldNames[el.getAttribute('name')])}
function bindMoneyInput(input){if(!input||input.dataset.moneyBound)return;input.dataset.moneyBound='1';if(input.type==='number')input.type='text';input.inputMode='decimal';input.autocomplete='off';const apply=function(pad){const start=input.selectionStart||0;const marks=input.value.slice(0,start).replace(/[^\d,]/g,'').length;const formatted=normalizeMoneyInput(input.value,pad);if(input.value!==formatted)input.value=formatted;if(document.activeElement!==input)return;if(!marks){input.setSelectionRange(0,0);return}let seen=0,pos=0;for(;pos<formatted.length;pos++){if(/[\d,]/.test(formatted[pos]))seen++;if(seen>=marks){pos++;break}}input.setSelectionRange(pos,pos)};input.addEventListener('input',function(){apply(false)});input.addEventListener('blur',function(){apply(true)});if(input.value)input.value=normalizeMoneyInput(input.value,true)}
function scanMoneyInputs(root){if(!root||!root.querySelectorAll)return;if(isMoneyField(root))bindMoneyInput(root);root.querySelectorAll('input').forEach(function(el){if(isMoneyField(el))bindMoneyInput(el)})}
scanMoneyInputs(document);
new MutationObserver(function(mutations){mutations.forEach(function(mutation){mutation.addedNodes.forEach(function(node){if(node.nodeType===1)scanMoneyInputs(node)})})}).observe(document.body,{childList:true,subtree:true});
